PRAGMA foreign_keys=ON;
CREATE TABLE "Categories" ("Id" INTEGER NOT NULL CONSTRAINT "PK_Categories" PRIMARY KEY AUTOINCREMENT,"Name" TEXT NOT NULL);
CREATE TABLE "Products" ("Id" INTEGER NOT NULL CONSTRAINT "PK_Products" PRIMARY KEY AUTOINCREMENT,"Name" TEXT NOT NULL,"Key" TEXT NOT NULL,"Price" INTEGER NOT NULL CHECK("Price">0),"CategoryId" INTEGER NOT NULL,"Active" INTEGER NOT NULL DEFAULT 1,FOREIGN KEY("CategoryId") REFERENCES "Categories"("Id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "IX_Products_Key_CategoryId" ON "Products"("Key","CategoryId");
CREATE INDEX "IX_Products_CategoryId" ON "Products"("CategoryId");
CREATE TABLE "Customers" ("Id" INTEGER NOT NULL CONSTRAINT "PK_Customers" PRIMARY KEY AUTOINCREMENT,"Name" TEXT NOT NULL,"Ci" TEXT NOT NULL,"Contact" TEXT NOT NULL);
CREATE UNIQUE INDEX "IX_Customers_Ci" ON "Customers"("Ci");
CREATE TABLE "Sales" ("Id" INTEGER NOT NULL CONSTRAINT "PK_Sales" PRIMARY KEY AUTOINCREMENT,"Date" TEXT NOT NULL,"CustomerId" INTEGER NULL,"Payment" TEXT NOT NULL CHECK("Payment" IN ('EFECTIVO','QR')),"RequestId" TEXT NOT NULL,"Subtotal" INTEGER NOT NULL,"Discount" INTEGER NOT NULL,"Total" INTEGER NOT NULL,FOREIGN KEY("CustomerId") REFERENCES "Customers"("Id") ON DELETE RESTRICT);
CREATE INDEX "IX_Sales_Date" ON "Sales"("Date");
CREATE INDEX "IX_Sales_CustomerId" ON "Sales"("CustomerId");
CREATE UNIQUE INDEX "IX_Sales_RequestId" ON "Sales"("RequestId");
CREATE TABLE "SaleLine" ("Id" INTEGER NOT NULL CONSTRAINT "PK_SaleLine" PRIMARY KEY AUTOINCREMENT,"SaleId" INTEGER NOT NULL,"ProductId" INTEGER NOT NULL,"Name" TEXT NOT NULL,"UnitPrice" INTEGER NOT NULL,"Quantity" INTEGER NOT NULL CHECK("Quantity">0),"Discount" INTEGER NOT NULL,"Total" INTEGER NOT NULL,"Promotion" TEXT NOT NULL,FOREIGN KEY("SaleId") REFERENCES "Sales"("Id") ON DELETE CASCADE,FOREIGN KEY("ProductId") REFERENCES "Products"("Id") ON DELETE RESTRICT);
CREATE INDEX "IX_SaleLine_SaleId" ON "SaleLine"("SaleId");
CREATE INDEX "IX_SaleLine_ProductId" ON "SaleLine"("ProductId");
CREATE TABLE "Promotions" ("Id" INTEGER NOT NULL CONSTRAINT "PK_Promotions" PRIMARY KEY AUTOINCREMENT,"Name" TEXT NOT NULL,"Description" TEXT NOT NULL,"Type" TEXT NOT NULL,"Value" TEXT NOT NULL,"Start" TEXT NOT NULL,"End" TEXT NOT NULL,"Active" INTEGER NOT NULL);
CREATE TABLE "PromotionProduct" ("PromotionId" INTEGER NOT NULL,"ProductId" INTEGER NOT NULL,CONSTRAINT "PK_PromotionProduct" PRIMARY KEY("PromotionId","ProductId"),FOREIGN KEY("PromotionId") REFERENCES "Promotions"("Id") ON DELETE CASCADE,FOREIGN KEY("ProductId") REFERENCES "Products"("Id") ON DELETE CASCADE);
CREATE INDEX "IX_PromotionProduct_ProductId" ON "PromotionProduct"("ProductId");
CREATE TABLE "PromotionCustomer" ("PromotionId" INTEGER NOT NULL,"CustomerId" INTEGER NOT NULL,CONSTRAINT "PK_PromotionCustomer" PRIMARY KEY("PromotionId","CustomerId"),FOREIGN KEY("PromotionId") REFERENCES "Promotions"("Id") ON DELETE CASCADE,FOREIGN KEY("CustomerId") REFERENCES "Customers"("Id") ON DELETE CASCADE);
CREATE INDEX "IX_PromotionCustomer_CustomerId" ON "PromotionCustomer"("CustomerId");
INSERT INTO "Categories"("Name") VALUES ('Helados'),('Hamburguesas'),('Bebidas'),('Sándwiches y croissants'),('Salchipapas'),('Platos de pollo'),('Empanadas'),('Cafetería'),('Jugos naturales'),('Postres');
